export type AppRoute = keyof AppRoutes;
export type AppRequest<R extends AppRoute> = AppRoutes[R]["request"];
export type AppResponse<R extends AppRoute> = AppRoutes[R]["response"];
export type AppError = ErrorResponse | ConflictResponse | NotBuiltResponse;

// Includes transport frames and the separate process.output / ai.* follow streams.
export interface AppEvents {
  "activity": Activity;
  "agent.changed": AgentEvent;
  "agent.created": AgentEvent;
  "agent.removed": AgentEvent;
  "ai.delta": AIDeltaEvent;
  "ai.done": AICallResponse;
  "ask.created": AskEvent;
  "ask.resolved": AskEvent;
  "ask.withdrawn": AskEvent;
  "crew.changed": CrewChangedEvent;
  "crew.created": CrewChangedEvent;
  "crew.log": CrewLogEvent;
  "factory.changed": FactoryChangedEvent;
  "factory.event": FactoryEvent;
  "hello": StreamHelloEvent;
  "inbox.added": InboxAddedEvent;
  "inbox.resolved": InboxResolvedEvent;
  "inbox.undo_window": InboxUndoWindowEvent;
  "keys.changed": KeysChangedEvent;
  "memory.changed": IDChangedEvent;
  "order.changed": OrderChangedEvent;
  "order.fired": OrderFiredEvent;
  "process.changed": ProcessChangedEvent;
  "process.output": ProcessOutputEvent;
  "queue.changed": QueueChangedEvent;
  "quick_task.changed": QuickTaskChangedEvent;
  "report.ready": ReportReadyEvent;
  "reset": StreamResetEvent;
  "role.changed": IDChangedEvent;
  "rule.changed": IDChangedEvent;
  "rule.created": IDChangedEvent;
  "settings.changed": KeysChangedEvent;
  "spend.changed": SpendChangedEvent;
  "task.changed": TaskChangedEvent;
  "task.created": TaskChangedEvent;
  "title.changed": TitleChangedEvent;
  "turn.delta": TurnDeltaEvent;
  "turn.ended": TurnLifecycleEvent;
  "turn.entry": TurnEntryEvent;
  "turn.long": TurnLongEvent;
  "turn.started": TurnLifecycleEvent;
}

export type AppEventName = keyof AppEvents;
export type AppEvent<N extends AppEventName = AppEventName> = {
  [K in N]: { event: K; data: AppEvents[K] }
}[N];
